// Package auth0device implements the OAuth 2.0 Device Authorization Grant
// (RFC 8628) against the Shadeform Auth0 tenant.
//
// It is what `shade auth login` uses to sign a person in from a terminal:
// the CLI asks Auth0 for a short code, the person confirms it in a browser
// on any device, and the CLI polls until Auth0 hands back an access token.
// Nothing listens on the local machine and there is no client secret: the
// client ID below identifies a public Native application and is safe to
// ship in the binary.
//
// This package is hand-written, not generated by Speakeasy.
package auth0device

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"os/exec"
	"runtime"
	"strings"
	"time"
)

const (
	// DefaultDomain is the customer Auth0 tenant's custom domain.
	DefaultDomain = "auth.shadeform.ai"
	// DefaultAudience is the Shadeform API's identifier in Auth0: the value a
	// token's aud claim must carry for api.shadeform.ai to accept it.
	DefaultAudience = "https://api.shadeform.ai"
	// DefaultClientID identifies the "Shadeform CLI" Native application on
	// the tenant. A Native application is a public client: it has no secret,
	// and its client ID is meant to ship inside distributed binaries. Holding
	// the ID only lets you start a device flow that a signed-in user still
	// has to approve on auth.shadeform.ai.
	DefaultClientID = "TI0huqTByjfE3iQ5CWqaC4Uqh5X4Vhkz"

	// Environment variables that override the defaults, for a staging tenant
	// or a local test server. The domain may be a bare host or a full URL.
	EnvDomain   = "SHADEFORM_AUTH0_DOMAIN"
	EnvClientID = "SHADEFORM_AUTH0_CLIENT_ID"
	EnvAudience = "SHADEFORM_AUTH0_AUDIENCE"

	defaultScope = "openid email"
	// Auth0 returns interval=5; RFC 8628 says default to 5 when absent.
	defaultInterval = 5 * time.Second
	// slow_down means add five seconds to the interval (RFC 8628 §3.5).
	slowDownStep = 5 * time.Second
)

// Config is the tenant and client the flow runs against.
type Config struct {
	// BaseURL is the tenant origin, e.g. https://auth.shadeform.ai.
	BaseURL  string
	ClientID string
	Audience string
	Scope    string
	HTTP     *http.Client
}

// DefaultConfig returns the production tenant, with environment overrides.
func DefaultConfig() Config {
	cfg := Config{
		BaseURL:  "https://" + DefaultDomain,
		ClientID: DefaultClientID,
		Audience: DefaultAudience,
		Scope:    defaultScope,
		HTTP:     &http.Client{Timeout: 30 * time.Second},
	}
	if v := strings.TrimSpace(os.Getenv(EnvDomain)); v != "" {
		if strings.Contains(v, "://") {
			cfg.BaseURL = strings.TrimRight(v, "/")
		} else {
			cfg.BaseURL = "https://" + strings.TrimRight(v, "/")
		}
	}
	if v := strings.TrimSpace(os.Getenv(EnvClientID)); v != "" {
		cfg.ClientID = v
	}
	if v := strings.TrimSpace(os.Getenv(EnvAudience)); v != "" {
		cfg.Audience = v
	}
	return cfg
}

// ErrNotConfigured is returned when no client ID is known. It is a
// configuration problem on our side, not the user's.
var ErrNotConfigured = errors.New("auth0device: no client ID configured; set " + EnvClientID + " or use --api-key")

// DeviceCode is Auth0's response to the device code request.
type DeviceCode struct {
	DeviceCode              string `json:"device_code"`
	UserCode                string `json:"user_code"`
	VerificationURI         string `json:"verification_uri"`
	VerificationURIComplete string `json:"verification_uri_complete"`
	ExpiresIn               int    `json:"expires_in"`
	Interval                int    `json:"interval"`
}

// Token is the access token Auth0 issues once the user has confirmed.
// The CLI uses it for one request and discards it; it is never stored.
type Token struct {
	AccessToken string `json:"access_token"`
	TokenType   string `json:"token_type"`
	ExpiresIn   int    `json:"expires_in"`
	Scope       string `json:"scope"`
}

var (
	// ErrAccessDenied: the user declined, or the Native app is not
	// authorized for the audience.
	ErrAccessDenied = errors.New("sign-in was declined")
	// ErrExpired: the user did not confirm before the code expired.
	ErrExpired = errors.New("the sign-in code expired before it was confirmed")
)

// RequestDeviceCode starts the flow.
func (c Config) RequestDeviceCode(ctx context.Context) (*DeviceCode, error) {
	if c.ClientID == "" {
		return nil, ErrNotConfigured
	}
	form := url.Values{
		"client_id": {c.ClientID},
		"scope":     {c.Scope},
		"audience":  {c.Audience},
	}
	var dc DeviceCode
	if err := c.post(ctx, "/oauth/device/code", form, &dc); err != nil {
		return nil, fmt.Errorf("requesting a sign-in code from %s: %w", c.BaseURL, err)
	}
	if dc.DeviceCode == "" || dc.UserCode == "" {
		return nil, fmt.Errorf("requesting a sign-in code from %s: response had no code", c.BaseURL)
	}
	return &dc, nil
}

// Sleep is how Poll waits between attempts. Tests replace it.
var Sleep = func(ctx context.Context, d time.Duration) error {
	t := time.NewTimer(d)
	defer t.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-t.C:
		return nil
	}
}

// Poll exchanges the device code for a token, waiting as RFC 8628 directs
// until the user confirms, declines, or the code expires.
func (c Config) Poll(ctx context.Context, dc *DeviceCode) (*Token, error) {
	interval := defaultInterval
	if dc.Interval > 0 {
		interval = time.Duration(dc.Interval) * time.Second
	}
	// Auth0 always sends expires_in; a missing value falls back to Auth0's
	// default lifetime so the loop still ends.
	deadline := time.Now().Add(time.Duration(dc.ExpiresIn) * time.Second)
	if dc.ExpiresIn == 0 {
		deadline = time.Now().Add(15 * time.Minute)
	}
	form := url.Values{
		"grant_type":  {"urn:ietf:params:oauth:grant-type:device_code"},
		"device_code": {dc.DeviceCode},
		"client_id":   {c.ClientID},
	}
	for {
		if err := Sleep(ctx, interval); err != nil {
			return nil, err
		}
		if time.Now().After(deadline) {
			return nil, ErrExpired
		}
		var tok Token
		err := c.post(ctx, "/oauth/token", form, &tok)
		if err == nil {
			if tok.AccessToken == "" {
				return nil, errors.New("sign-in completed but no access token was returned")
			}
			return &tok, nil
		}
		var oe *oauthError
		if !errors.As(err, &oe) {
			return nil, fmt.Errorf("waiting for sign-in: %w", err)
		}
		switch oe.Code {
		case "authorization_pending":
			continue
		case "slow_down":
			interval += slowDownStep
			continue
		case "expired_token":
			return nil, ErrExpired
		case "access_denied":
			return nil, ErrAccessDenied
		default:
			return nil, fmt.Errorf("waiting for sign-in: %w", oe)
		}
	}
}

// oauthError is the body Auth0 returns on a 4xx from either endpoint. The
// field is named Code rather than Error so the type can implement error.
type oauthError struct {
	Code        string `json:"error"`
	Description string `json:"error_description"`
}

func (e *oauthError) Error() string {
	if e.Description != "" {
		return e.Code + ": " + e.Description
	}
	return e.Code
}

// post sends a form-encoded request and decodes JSON. A 4xx with an OAuth
// error body is returned as *oauthError so Poll can branch on the code.
func (c Config) post(ctx context.Context, path string, form url.Values, out any) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.BaseURL+path, strings.NewReader(form.Encode()))
	if err != nil {
		return err
	}
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	req.Header.Set("Accept", "application/json")
	httpClient := c.HTTP
	if httpClient == nil {
		httpClient = http.DefaultClient
	}
	resp, err := httpClient.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return err
	}
	if resp.StatusCode >= 400 {
		var oe oauthError
		if json.Unmarshal(body, &oe) == nil && oe.Code != "" {
			return &oe
		}
		return fmt.Errorf("%s returned HTTP %d", path, resp.StatusCode)
	}
	return json.Unmarshal(body, out)
}

// OpenBrowser opens url with the platform's default handler. It returns an
// error rather than printing anything, so the caller can fall back to
// showing the URL.
func OpenBrowser(url string) error {
	var cmd *exec.Cmd
	switch runtime.GOOS {
	case "darwin":
		cmd = exec.Command("open", url)
	case "windows":
		cmd = exec.Command("rundll32", "url.dll,FileProtocolHandler", url)
	default:
		cmd = exec.Command("xdg-open", url)
	}
	cmd.Stdout, cmd.Stderr = io.Discard, io.Discard
	return cmd.Start()
}
